Running command: cat > /tmp/test_poc.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <open62541/types.h>
#include <open62541/types_generated_handling.h>
#include "ua_types_encoding_json.h"

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    UA_Byte *data = (UA_Byte*)malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    UA_ByteString buf;
    buf.data = data;
    buf.length = size;

    UA_Variant out;
    UA_Variant_init(&out);

    UA_StatusCode retval = UA_decodeJson(&buf, &out, &UA_TYPES[UA_TYPES_VARIANT]);
    printf("retval = 0x%08x\n", retval);
    if(retval == UA_STATUSCODE_GOOD)
        UA_Variant_deleteMembers(&out);

    free(data);
    return 0;
}
EOF
echo "Test harness created"

